    [
        'slug' => 'the-quiet-return-of-the-neighbourhood-kopitiam',
        'desk' => 'Makanan',
        'title' => 'Kopitiam kejiranan yang kembali senyap-senyap',
        'deck' => 'Generasi muda kini mengambil alih kedai kopi di simpang jalan, dan bersungguh-sungguh cuba untuk tidak mengubah apa-apa.',
        'byline' => 'Oleh meja makanan Meridian',
        'sections' => [
            ['name' => 'Tuangan pertama', 'blocks' => [
                ['type' => 'p', 'text' => 'Pukul tujuh pagi hari Selasa, bunyi paling kuat di Kedai Kopi Lam Fatt ialah cerek. Uncle Keong, 71, menuang air dari paras bahu ke dalam penapis kain yang sudah bertukar warna seperti jati lama. Sudah 48 tahun dia membancuh kopi begini. Di sebelahnya, anak saudaranya, Mei Ling, menyandarkan telefon pada tin gula dan merakam gerak tangan Uncle Keong.'],
                ['type' => 'p', 'text' => 'Video itu bukan untuk media sosial. Dia sedang cuba mencatat resipinya, kerana Uncle Keong tidak pernah menyukat apa-apa.'],
                ['type' => 'p', 'text' => '“Dia cakap ‘sampai bau dah betul’,” kata Mei Ling. “Itu bukan resipi. Itu ugutan.”'],
                ['type' => 'p', 'text' => 'Mei Ling, 34, meninggalkan kerjanya di Kuala Lumpur tahun lalu untuk mengambil alih kedai ini. Dia sebahagian daripada satu gerakan kecil yang tidak diumumkan sesiapa di Ipoh, Pulau Pinang dan kawasan lama Klang: anak dan cucu yang pulang ke kedai kopi simpang jalan yang hampir ditutup oleh keluarga mereka.'],
            ]],
            ['name' => 'Serah terima', 'blocks' => [
                ['type' => 'p', 'text' => 'Sekian lama, kisah kopitiam hanya menuju satu arah. Pemiliknya makin tua. Anak-anak mereka menjadi akauntan. Bangunannya dijual, lalu kedai telefon atau rangkaian bubble tea masuk menggantikannya. Meja marmarnya pula berakhir di kafe entah siapa di Bangsar, dengan tanda harga barang antik.'],
                ['type' => 'p', 'text' => 'Apa yang berubah lebih sukar dijelaskan daripada sekadar trend. Ada yang terpaksa pulang, sama ada kerana dibuang kerja atau kerana orang tua jatuh sakit. Ada pula yang mencongak gaji bandar dan sewa bandar, lalu memutuskan bahawa lot kedai yang sudah habis dibayar lebih bernilai daripada kedua-duanya.'],
                ['type' => 'p', 'text' => '“Saya ingat saya balik enam bulan saja,” kata Farid, 29, yang kini mengusahakan kedai arwah datuknya bersama saudara perempuannya, di sederet kedai yang sunyi berhampiran landasan kereta api lama. “Kemudian saya nampak pelanggan tetap. Tak ada siapa beritahu saya, orangnya pun kita warisi sekali.”'],
                ['type' => 'p', 'text' => 'Mewarisi orang, rupa-rupanya, itulah bahagian yang paling payah. Pelanggan tetap banyak pendapat. Apabila Mei Ling mengalihkan meja juruwang satu meter ke kiri, tiga pelanggan merungut dalam satu pagi. Dia mengalihkannya semula.'],
                ['type' => 'p', 'text' => 'Farid juga mewarisi buku hutang datuknya, yang mencatat siapa berhutang berapa. Ada hutang yang bermula sejak 1994. Dia tidak bercadang untuk menuntutnya. Pada petang yang lengang, dia membaca nama-nama itu dengan kuat, dan sekali-sekala seseorang di meja sebelah akan berkata lelaki itu bapanya.'],
            ]],
            ['name' => 'Yang kekal', 'blocks' => [
                ['type' => 'p', 'text' => 'Para pemilik baharu ini berhati-hati memilih apa yang hendak disentuh. Masuklah ke mana-mana kedai ini, dan perubahannya kecil sahaja: mesin kad yang dilekatkan dengan pita di sebelah mesin tunai, menu yang akhirnya menyenaraikan harga, kipas yang boleh berpusing. Kerusinya kekal. Bisingnya pun sama.'],
                ['type' => 'p', 'text' => 'Paling penting, kopinya kekal. Biji kopi masih digoreng hingga gelap dengan gula dan marjerin, kemudian dibancuh pekat melalui kain dan dituang dari tempat tinggi supaya sejuk sedikit. Bahasanya juga kekal, dan pelanggan baharu diharap pandai belajar.'],
                ['type' => 'guide', 'title' => 'Cara memesan di kaunter', 'rows' => [
                    ['term' => 'Kopi', 'meaning' => 'Kopi dengan susu pekat manis'],
                    ['term' => 'Kopi-O', 'meaning' => 'Kopi hitam, bergula'],
                    ['term' => 'Kopi-O kosong', 'meaning' => 'Kopi hitam, tanpa gula'],
                    ['term' => 'Kopi-C', 'meaning' => 'Dengan susu cair dan gula'],
                    ['term' => 'Peng', 'meaning' => 'Dengan ais. Tambah pada mana-mana pesanan'],
                ]],
                ['type' => 'p', 'text' => 'Kalau pemilik muda ini mencuba sesuatu, biasanya di pinggir sahaja. Saudara perempuan Farid menambah nasi lemak pada hari Sabtu, mengikut resipi seorang mak cik, dan habis menjelang pukul sepuluh. Mei Ling pula membuka kedai pada petang Ahad, buat pertama kali dalam sejarah kedai itu, dan mendapati ramai remaja datang membuat kerja sekolah di bawah lampu kalimantang.'],
            ]],
            ['name' => 'Untuk siapa', 'blocks' => [
                ['type' => 'p', 'text' => 'Semua ini ada risikonya, dan para pemilik tahu. Kopitiam yang dipulihkan memang cantik dalam gambar. Sebaik sahaja sebuah kedai menjadi destinasi, orang yang menjadikannya berbaloi dikunjungi boleh hilang tempat di meja sendiri kerana harga.'],
                ['type' => 'p', 'text' => 'Secawan kopi-o di Lam Fatt masih lebih murah daripada tambang bas. Mei Ling pernah menaikkan harganya sekali, sebanyak dua puluh sen, dan tidak lena tidur kerananya. Dia lebih risau tentang pengunjung hujung minggu yang duduk sejam, memesan satu minuman dan mengambil gambar jubin lantai.'],
                ['type' => 'pullquote', 'text' => 'Peguam dan pemandu lori berkongsi meja dan tak ada siapa rasa pelik.'],
                ['type' => 'p', 'text' => '“Di bandar ini, tinggal kopitiam saja tempat peguam dan pemandu lori berkongsi meja dan tak ada siapa rasa pelik,” katanya. “Kalau yang datang peguam saja, maknanya saya cuma buka kafe.”'],
                ['type' => 'p', 'text' => 'Uncle Keong kurang risau. Dia sudah melihat kedai ini bertahan melalui banjir, dua kemelesetan dan kemunculan kopi segera. Soal pelancong, dia memandang jauh, seperti dalam kebanyakan hal.'],
            ]],
            ['name' => 'Waktu tutup', 'blocks' => [
                ['type' => 'p', 'text' => 'Menjelang pukul dua petang, kedai hampir kosong. Cerek semakin sejuk. Mei Ling sudah sebelas hari merakam pada waktu pagi, dan buku notanya kini berisi semacam resipi: sukatan berat, suhu dan satu lajur panjang tekaan yang sudah dipangkah.'],
                ['type' => 'p', 'text' => 'Minggu lalu dia membancuh seteko kopi mengikut resipi itu, lalu memberi Uncle Keong secawan tanpa berkata apa-apa. Lelaki tua itu minum perlahan-lahan sambil memandang ke jalan.'],
                ['type' => 'p', 'text' => '“Hampir,” katanya, lalu menyambung membaca surat khabar.'],
                ['type' => 'p', 'text' => 'Bagi Mei Ling, itulah ulasan terbaik yang diterima kedai ini sejak bertahun-tahun lalu.'],
            ]],
        ],
